INSERT INTO `highlights` (`id`, `title`, `description`, `status`, `added_by`, `featured_image`, `created_at`, `updated_at`) VALUES
(21, 'International Conference on IFRS and NFRS held in Kathmandu', '<p><img src=\"/upload/highlight/highlight_1668404369.jpg\" alt=\"\" width=\"2048\" height=\"1155\" />November 14, 202: International Conference on International Financial Reporting Standards (IFRS) and National Financial Reporting Standards (NFRS) commenced in the capital city, Kathmandu at Soaltee Hotel on November 13, 202.</p>\r\n<p>Over 100 participants representing various microfinance companies participated in the conference.&nbsp;</p>\r\n<p><img src=\"/upload/highlight/highlight_1668404413.jpg\" alt=\"\" width=\"2048\" height=\"1155\" /></p>\r\n<p>Chief Executive Officer of Aatmanirbbhar LBS Saugat Bir Chaudhary, Internal Auditor Nep Bahadur Chaudhary, HR officer Kalidas Chaudhary, IT officer Subir Chaudhary and Finance officer Himal Chaudhary on behalf of Aatmanirbhar LBS have also taken part in the conference.</p>\r\n<p>More details to follow later:&nbsp;</p>\r\n<p><img src=\"/upload/highlight/highlight_1668404448.jpg\" alt=\"\" width=\"2048\" height=\"1155\" /></p>\r\n<p><img src=\"/upload/highlight/highlight_1668404474.jpg\" alt=\"\" width=\"2048\" height=\"1155\" /></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', 'active', 'Subir', '314573975_867661611345124_112680891195064098_n.jpg', '2022-11-13 23:56:47', '2022-11-14 00:00:03'),
(23, 'Financial Literacy Training being imparted to members', '<p><img src=\"/upload/highlight/highlight_1676794250.jpg\" alt=\"\" width=\"1080\" height=\"810\" />Feb 19,2023: Aatmanirbhar LBS has initiated conducting financial literacy training to its group members in various branches to disseminate various laghubitta related informations to members.</p>\r\n<p><img src=\"/upload/highlight/highlight_1676794278.jpg\" alt=\"\" width=\"2048\" height=\"1536\" /></p>\r\n<p>The literacy trainings were imparted by Nep Bahadur Chaudhary, Nirmal Chaudhary, Binaya Chaudhary and Puran Adhikari with the support of respective branch managers in Dang, Banke and Bardia.</p>\r\n<p><img src=\"/upload/highlight/highlight_1676794325.jpg\" alt=\"\" /></p>\r\n<p>These trainings focussed on how to make regular savings, and how to make use of small loans taken by investing them in the profitable business.</p>', 'active', 'Subir', 'Fin lit training.jpg', '2023-02-19 02:27:38', '2023-02-19 02:30:16'),
(24, 'आत्मनिर्भर लघुवित्तले बिहिबारदेखि आइपीओ निष्काशन गर्दै', '<p><img src=\"/upload/highlight/highlight_1676993065.png\" alt=\"\" width=\"5992\" height=\"1080\" />काठमाडौं । ओपनिङ रेञ्ज नै हजार भन्दा माथि हुने आत्मनिर्भर लघुवित्त वित्तीय संस्थाले बिहिबार (फागुन ११ गते)देखि आइपीओ निष्काशन गर्दैछ । संस्थाले वैदेशिक रोजगारमा गएका नेपालीहरुका लागि आइपीओ निष्काशन गरेपछि सर्वसाधारणका लागि आइपीओ जारी गर्न लागेको हो ।</p>\r\n<p>आत्मनिर्भर लघुवित्तले आफ्नो जारी पुँजीको ६ करोड २३ लाख ३८ हजार रुपैयाँको ३२.६२५% ले हुन आउने २ करोड ३ लाख ३८ हजार रुपैयाँ बराबरको आइपीओ बिक्री गर्न खोजेको हो ।</p>\r\n<p>जसअनुसार प्रतिसेयर १०० रुपैयाँ अंकित मूल्यमा २ लाख ३ हजार ३८० कित्ता सेयर निष्कासन हुनेछ । यसमध्ये १०% अर्थात् २० हजार ३३८ कित्ता सेयर वैदेशिक रोजगारीमा रहेका नेपालीहरुलाई निष्कासन गरिएको छ । यस्तै, जारी पुँजीको ०.५% अर्थात् ३ हजार ११७ कित्ता सेयर कर्मचारीलाई र ५% अर्थात् १० हजार १७० कित्ता सामूहिक लगानी कोषका लागि सुरक्षित गरिएको छ । बाँकी रहेको १ लाख ६९ हजार ७५५ कित्ता सेयरमा सर्वसाधारण लगानीकर्ताले आवेदन दिन सक्नेछन् ।</p>\r\n<p>सर्वसाधारण लगानीकर्ताले यसमा फागुन १५ गतेसम्म आवेदन दिन पाउनेछन् । सो अवधिमा सबै सेयर बिक्री नभएमा भने फागुन २५ गतेसम्म पनि भर्न पाइनेछ । यसमा न्यूनतम १० कित्तादेखि अधिकतम १ हजार कित्ताका लागि आवेदन दिन पाइनेछ । आवेदकले सि&ndash;आस्वा सदस्य बैंक तथा वित्तीय संस्थाबाट र सीडीएस एण्ड क्लियरिङ्गको वेबसाइट मेरो शेयरबाट आवेदन दिन सक्नेछन् ।</p>\r\n<p>कम्पनीको आर्थिक वर्ष २०७७।७८ को वास्तविक प्रतिशेयर ३७१.८२ रुपैयाँ रहेको छ । यसर्थ सो कम्पनीको शेयरपाउने भाग्यमानी लगानीकर्ता मालामाल हुनेछन् । नेप्सेले वास्तविक प्रतिशेयर नेटवर्थको आधारमा ओपनिङ्ग प्राइस तोक्ने गर्दछ । यसर्थ लघुवित्तको आइपीओले पहिलो कारोबारका लागि ओपनिङ्ग रेञ्ज नै ३७१ रुपैयाँ ८० पैसादेखि १११५ रुपैयाँ ४ पैसा पाउने देखिएको छ ।</p>', 'active', 'Subir', NULL, '2023-02-21 09:39:47', '2023-02-21 09:39:47'),
